import React from "react";
import { Link } from "react-router-dom";
import { Button, Container, Typography, Grid, Card, CardContent } from "@mui/material";

const features = [
  {
    title: "Website Monitoring",
    description: "Track server health, database performance, and network activity in real-time.",
  },
  {
    title: "Predictive Maintenance",
    description: "AI-powered insights to predict and prevent bugs and issues before they occur.",
  },
  {
    title: "Automation",
    description: "Automate bug resolution and system recovery with advanced algorithms.",
  },
  {
    title: "User-Friendly Dashboard",
    description: "Intuitive and responsive dashboards for seamless management.",
  },
];

const Home = () => {
  return (
    <div className="bg-gray-50 min-h-screen">
      {/* Welcome Section */}
      <div
        className="bg-cover bg-center text-white py-20 text-center"
        style={{
          backgroundImage: "url('https://source.unsplash.com/1600x900/?technology,data')", // Replace with your desired image URL
        }}
      >
        <Typography variant="h2" className="font-bold mb-4 drop-shadow-lg">
          Welcome to OptiWeb Zone
        </Typography>
        <Typography variant="h6" className="mb-8 drop-shadow-lg">
          Your one-stop solution for website monitoring, predictive maintenance, and automation.
        </Typography>
        <div className="flex justify-center gap-4">
          <Link to="/register">
            <Button variant="contained" color="secondary" size="large">
              Register
            </Button>
          </Link>
          <Link to="/login">
            <Button variant="outlined" color="inherit" size="large">
              Login
            </Button>
          </Link>
        </div>
      </div>

      {/* Features Section */}
      <Container maxWidth="lg" className="py-16">
        <Typography variant="h4" className="text-center font-semibold mb-8">
          OptiWeb Features
        </Typography>
        <Grid container spacing={4}>
          {features.map((feature, index) => (
            <Grid item xs={12} sm={6} md={3} key={index}>
              <Card
                className="shadow-md hover:shadow-xl transition duration-300"
                style={{ backgroundColor: "#f9f9f9" }}
              >
                <CardContent>
                  <Typography variant="h6" className="font-bold mb-2">
                    {feature.title}
                  </Typography>
                  <Typography variant="body2" className="text-gray-600">
                    {feature.description}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      </Container>
    </div>
  );
};

export default Home;
